// Normaliza o retorno do CRM sem alterar ou reenviar o cadastro.
// Aceita apenas os avisos conhecidos de email opcional e janela fechada antes do JSON.
function normalizarResposta(response) {
  const httpStatus = Number.isInteger(response.statusCode) ? response.statusCode : null;
  const avisos = [];
  let body = response.body;
  if (typeof body === 'string') {
    body = body.trim();
    while (body.startsWith('<div')) {
      const block = body.match(/^<div\b[^>]*>[\s\S]*?<\/div>\s*/i);
      if (!block) break;
      const text = block[0].replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
      const knownNotice = text.includes('A PHP Error was encountered')
        && /Severity:\s*Notice\b/.test(text)
        && /Message:\s*Undefined property:\s*stdClass::\$email\b/.test(text)
        && /Filename:\s*controllers\/leads\.php\b/.test(text);
      if (!knownNotice) break;
      avisos.push('crm_email_opcional_ausente');
      body = body.slice(block[0].length).trim();
    }
    const windowNotice = 'Mensagem de janela fechada já foi enviada há menos de 24 horas. Não enviar novamente.';
    if (body.startsWith(windowNotice)) {
      avisos.push('crm_mensagem_janela_fechada_nao_reenviada');
      body = body.slice(windowNotice.length).trim();
    }
    try {
      body = JSON.parse(body);
    } catch {
      body = null;
    }
  }
  const validObject = body !== null && typeof body === 'object' && !Array.isArray(body);
  const apiCode = validObject && (typeof body.code === 'number' || typeof body.code === 'string')
    && /^\d{3}$/.test(String(body.code)) ? Number(body.code) : null;
  const apiSuccess = validObject && body.status === 'success' && apiCode === 200;
  const httpSuccess = httpStatus !== null && httpStatus >= 200 && httpStatus < 300;
  const success = !response.error && httpSuccess && apiSuccess;
  let motivo = null;
  if (!success) {
    motivo = response.error ? 'erro_de_transporte'
      : !httpSuccess ? 'http_sem_confirmacao_de_sucesso'
      : !validObject ? 'resposta_crm_invalida'
      : 'crm_nao_confirmou_sucesso';
  }
  return {
    success,
    status: success ? 'success' : 'nao_confirmado',
    code: apiCode,
    http_status: httpStatus,
    avisos: [...new Set(avisos)],
    motivo,
    mensagem_retorno: success
      ? 'A API do CRM confirmou o recebimento do lead. Não repita este cadastro de lead. Se houve pedido de visita, ele foi encaminhado como pré-agendamento: o corretor ainda precisa confirmar a data e o horário. Não reproduza avisos técnicos ao lead.' + (avisos.includes('crm_mensagem_janela_fechada_nao_reenviada') ? ' A API também informou que não reenviou uma mensagem de janela fechada por já ter enviado há menos de 24 horas. Esse aviso não desfaz o recebimento do lead, mas não confirme um novo envio de notificação.' : '')
      : 'Não foi possível confirmar o recebimento do lead pelo CRM. Não diga que o cadastro, o encaminhamento ou o pré-agendamento foi concluído. Informe a dificuldade com naturalidade. Não repita automaticamente o cadastro, pois a tentativa pode ter sido processada. Não reproduza detalhes técnicos ao lead.',
  };
}
return $input.all().map((item, index) => ({
  json: normalizarResposta(item.json),
  pairedItem: { item: index },
}));

const raw = $input.item.json.imagens; // campo do banco
const images = typeof raw === 'string' ? JSON.parse(raw) : raw;
const phone = $('When Executed by Another Workflow').item.json.phone;

return images.slice(0, 5).map((url, i) => ({
  json: {
    imageUrl: url,
    phone: phone,
    caption: i === 0 ? "📸 Fotos do imóvel:" : ""
  }
}));

