// Pega todos os dados do body do webhook
const body = $('Webhook').first().json.body;

// Formata nome para Title Case (ex: "LUCAS CASTRO" → "Lucas Castro")
const formatarNome = (nome) => {
  if (!nome) return '';
  return nome
    .toLowerCase()
    .split(' ')
    .filter(p => p.length > 0)
    .map(p => {
      const preposicoes = ['de', 'da', 'do', 'dos', 'das', 'e'];
      if (preposicoes.includes(p)) return p;
      return p.charAt(0).toUpperCase() + p.slice(1);
    })
    .join(' ');
};

// Pega o telefone do webhook
let telefone = body.phone;

// 1. Remove tudo que não é dígito
telefone = telefone.replace(/\D/g, '');

// 2. Se começa com 0, remove (ex: 048...)
if (telefone.startsWith('0')) {
  telefone = telefone.substring(1);
}

// 3. Remove o 55 do início para trabalhar só com DDD+número
let semPais = telefone;
if (telefone.startsWith('55') && telefone.length >= 12) {
  semPais = telefone.substring(2);
}

// 4. Garante 11 dígitos (DDD + 9 + 8 dígitos)
if (semPais.length === 10) {
  semPais = semPais.substring(0, 2) + '9' + semPais.substring(2);
}

// 5. Se tem mais de 11 dígitos, trunca para 11
if (semPais.length > 11) {
  const ddd = semPais.substring(0, 2);
  const numero = semPais.slice(-9);
  semPais = ddd + numero;
}

// 6. Resultado final
const telefoneFormatado = '55' + semPais;

// Mapeia campos do Chaves na Mão para o padrão do fluxo
return [{ json: {
  ...body,
  name: formatarNome(body.name),
  phone: telefoneFormatado,
  email: body.email,
  internalReference: body.ad?.reference || '',
  origem: 'Chaves na Mão',
  origin_id: 42
} }];

