  telefone = telefone.substring(1);
}

let semPais = telefone;
if (telefone.startsWith('55') && telefone.length >= 12) {
  semPais = telefone.substring(2);
}

// Garante 9º dígito em números com 10 dígitos
if (semPais.length === 10) {
  semPais = semPais.substring(0, 2) + '9' + semPais.substring(2);
}

// Remove dígito extra se passar de 11
if (semPais.length > 11) {
  const ddd = semPais.substring(0, 2);
  const numero = semPais.slice(-9);
  semPais = ddd + numero;
}

const telefoneFormatado = '55' + semPais;

// --- Valor de investimento ---
const investimento = row['PRODUTO INTERESSADO'] || row.o_quanto_pretende_investir || '';

// --- Extrai apenas o primeiro nome ---
const nomeCompleto = row['NOME'] || row.full_name || '';
const primeiroNome = nomeCompleto.trim().split(' ')[0];

return [{ json: {
  name: primeiroNome,
  phone: telefoneFormatado,
  investimento: investimento,
  origem: 'Trafego'
} }];

