={{
  ((() => {
    const body = $('Webhook1').item.json.body;

    // --- Detecção do número bruto ---
    // Para documentos: tenta participant ou participantPn
    // Para mensagens de texto: usa remoteJid ou senderPn
    const raw = (
      body.key.participant
      || body.key.participantPn
      || (body.key.remoteJid?.includes('@s.whatsapp.net')
          ? body.key.remoteJid
          : body.key.senderPn)
    ) ?? '';

    // --- Normalização ---
    const n = String(raw)
      .replace('@s.whatsapp.net', '')
      .replace(/\D/g, '')       // Remove qualquer caractere não-numérico
      .replace(/^55/, '');      // Remove prefixo 55 (Brasil)

    // DDD + 8 dígitos (fixo) → adiciona 9º dígito para virar celular
    if (/^\d{10}$/.test(n)) return n.slice(0, 2) + '9' + n.slice(2);

    // DDD + 9 dígitos (celular já correto)
    return n;
  })())
}}

