parameters.jsCode:
const crypto = require('crypto');

const req     = $('Webhook').first().json;
const body    = req.body ?? {};
const headers = req.headers ?? {};
const secret  = $('Parametros do Fluxo').first().json.secret_bot;

// A Arini assina o corpo CRU com HMAC-SHA256. O corpo sai de um JSON.stringify,
// entao re-serializar reproduz a assinatura byte a byte — conferido contra a
// execucao 3181332 (648 bytes, bate com o content-length recebido).
// Por isso o Webhook NAO precisa de Raw Body, e o resto do fluxo continua lendo $json.body.
let assinatura_ok = false;
try {
  const recebida = String(headers['x-arini-signature'] || '');
  const esperada = 'sha256=' + crypto.createHmac('sha256', secret)
    .update(JSON.stringify(body)).digest('hex');
  const a = Buffer.from(recebida);
  const b = Buffer.from(esperada);
  assinatura_ok = a.length === b.length && crypto.timingSafeEqual(a, b);
} catch (e) {
  assinatura_ok = false;
}

const conversa = body.conversa ?? {};
const contato  = body.contato  ?? {};
const mensagem = body.mensagem ?? {};

const telefone      = String(contato.telefone ?? '').replace(/\D/g, '');
const nome_completo = String(contato.nome ?? '').trim();
const primeiro_nome = (nome_completo.replace(/[^\p{L}\p{N}\s]/gu, '').trim().split(/\s+/)[0]) || '';

return [{ json: {
  assinatura_ok,
  bot_id_recebido: headers['x-arini-bot'] ?? '',
  evento:      body.evento ?? '',
  enviado_em:  body.enviado_em ?? '',

  conversa_id:     conversa.id ?? '',
  canal:           conversa.canal ?? '',
  status_conversa: conversa.status ?? '',
  bot_status:      conversa.bot_status ?? '',
  etiquetas:       conversa.etiquetas ?? [],

  contato_id:    contato.id ?? '',
  nome_completo,
  primeiro_nome,
  telefone,
  email:         contato.email ?? '',

  mensagem_id: mensagem.id ?? '',
  direcao:     mensagem.direcao ?? '',
  remetente:   mensagem.remetente ?? '',
  tipo:        mensagem.tipo ?? '',
  texto:       mensagem.texto ?? '',
  media_url:   mensagem.media_url ?? '',
  media_nome:  mensagem.media_nome ?? '',
  media_mime:  mensagem.media_mime ?? '',

  // Chave de sessao: o contato e estavel entre conversas e canais.
  // Cai para telefone e, por ultimo, para a conversa.
  session_key: String(contato.id || telefone || conversa.id || '')
} }];

