parameters.jsCode:
// Pega os dados do lead do webhook
const webhookData = $('Webhook Novo Lead').item.json;
const body = webhookData.body || webhookData;

let telefone = String(body.TELEFONE || body.telefone || '');
telefone = telefone.replace(/\D/g, '');

if (telefone.startsWith('0')) {
  telefone = telefone.substring(1);
}

let semPais = telefone;
if (telefone.startsWith('55') && telefone.length >= 12) {
  semPais = telefone.substring(2);
}

if (semPais.length === 10) {
  semPais = semPais.substring(0, 2) + '9' + semPais.substring(2);
}

if (semPais.length > 11) {
  const ddd = semPais.substring(0, 2);
  const numero = semPais.slice(-9);
  semPais = ddd + numero;
}

const telefoneFormatado = '55' + semPais;

// --- Pega apenas o primeiro nome ---
const nomeCompleto = String(body.NOME || body.nome || '').trim();
const primeiroNome = nomeCompleto.split(' ')[0] || '';

// --- Padroniza referência do imóvel ---
const produtoInteressado = String(body['PRODUTO INTERESSADO'] || body.ref_imovel_cadastrado || '').trim();

const correcoes = {
  'torre di castoi': 'Torre Di Castroi',
};

let referencia = '';

const refMatch = produtoInteressado.match(/\d+/);

if (refMatch) {
  referencia = refMatch[0];
} else if (produtoInteressado) {
  const chave = produtoInteressado.toLowerCase();
  if (correcoes[chave]) {
    referencia = correcoes[chave];
  } else {
    referencia = produtoInteressado
      .toLowerCase()
      .split(' ')
      .map(p => p.charAt(0).toUpperCase() + p.slice(1))
      .join(' ');
  }
}

return [{ json: {
  name: primeiroNome,
  phone: telefoneFormatado,
  email: body.EMAIL || body.email || '',
  internalReference: referencia,
  origem: 'Meta Ads'
} }];

