assignments.value:
={{(() => {
  const root = $('Webhook').first().json ?? {};
  const body = root.body ?? root;

  // Best source: already plain text in conversation.messages[0].content
  const msg = body.conversation?.messages?.[0]?.content;
  if (typeof msg === 'string' && msg.trim()) return msg.trim();

  // Fallback: body.content often comes as HTML like "<p>Olá!</p>\n"
  const html = body.content;
  if (typeof html !== 'string') return '';

  const withoutTags = html.replace(/<[^>]*>/g, ' ');
  const decoded = withoutTags
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'");

  return decoded.replace(/\s+/g, ' ').trim();
})()}}

={{(() => {
  const root = $('Webhook').first().json ?? {};
  const body = root.body ?? root;

  const convo = body.conversation ?? body.current_conversation ?? {};
  const sender = body.sender ?? convo.meta?.sender ?? {};

  const conversationId = convo.id ?? '';
  const messageId = body.id ?? '';

  // Contexto Temporal
  const dataHora = $now.setLocale('pt-br').toFormat("cccc, dd/MM/yyyy, HH:mm");
  const timezone = $now.zoneName; 

  // 1. Identificação do Tipo de Mídia (Checa attachments)
  const atts = (body.attachments?.length ? body.attachments : (convo.messages?.[0]?.attachments ?? []));
  const hasAudio = atts.some(a => a.file_type === 'audio');
  const hasImage = atts.some(a => a.file_type === 'image');

  // Captura a legenda original do webhook (se houver)
  const legendaOriginal = body.content || '';

  // 2. Busca as mensagens do seu Buffer (Redis)
  const rawBuffered = (
    $('buffer1').item?.json?.messages ??
    $('buffer').item?.json?.messages ??
    []
  );

  let conteudoFinal = rawBuffered.join('\n\n').trim();
  let tipoMsgMeta = 'TEXTO_CHAT';

  // 3. Lógica de Estruturação por Tipo
  if (hasAudio) {
      tipoMsgMeta = 'AUDIO_VOICE';
      conteudoFinal = `
<origem_da_mensagem>O cliente enviou um áudio.</origem_da_mensagem>
<transcricao_de_audio>
  "${conteudoFinal}"
</transcricao_de_audio>
<instrucao_ia>O texto acima é a transcrição do áudio. Responda como se tivesse ouvido a voz dele.</instrucao_ia>`.trim();
  } 
  else if (hasImage) {
      tipoMsgMeta = 'IMAGEM_CONTEUDO';
      conteudoFinal = `
<origem_da_mensagem>O cliente enviou uma imagem acompanhada de texto.</origem_da_mensagem>
<legenda_do_cliente>
  "${legendaOriginal}"
</legenda_do_cliente>
<descricao_visual_da_imagem>
  "${conteudoFinal}"
</descricao_visual_da_imagem>
<instrucao_ia>Acima está o que o cliente escreveu e a descrição técnica da imagem. Use ambos para responder com naturalidade.</instrucao_ia>`.trim();
  }

  // 4. Retorno formatado para a IA
  return [
    '### DADOS DO CLIENTE',
    `Nome: ${sender.name || ''}`,
    `Telefone: ${sender.phone_number || ''}`,
    '',
    '### CONTEXTO TEMPORAL (IMPORTANTE)',
    `Data e Hora Atual: ${dataHora}`,
    `Timezone: ${timezone}`,
    '',
    '### METADADOS DO CHAT',
    `ID_Conversa: ${conversationId}`,
    `ID_Mensagem: ${messageId}`,
    `Tipo_Mensagem: ${tipoMsgMeta}`,
    '',
    '### CONTEÚDO DA MENSAGEM PARA PROCESSAR',
    conteudoFinal || '(vazio)'
  ].join('\n');
})()}}

